const AUDIT_ACTOR_ID_LABELS = {
  __admin__: 'Админ',
  система: 'Система',
  system: 'Система',
};

function auditActionLabel(action) {
  if (!action) return '—';
  const code = String(action);
  if (AUDIT_ACTION_LABELS[code]) return AUDIT_ACTION_LABELS[code];
  const m = /^marking\.scan\.(.+)$/.exec(code);
  if (m) {
    const sub =
      ({ receive: 'приёмка', sale: 'продажа', withdraw: 'вывод', return: 'возврат', defect: 'брак' })[
        m[1]
      ] || m[1];
    return `Скан маркировки: ${sub}`;
  }
  // Не показываем сырой код в UI — читаемая фраза
  const human = code
    .replace(/^crm\./, '')
    .replace(/^deal\./, '')
    .replace(/^sales[._]/, '')
    .replace(/^counterparty\./, '')
    .replace(/[._]+/g, ' ')
    .replace(/\bamo\b/gi, 'Amo')
    .replace(/\bvehicle\b/gi, 'авто')
    .replace(/\bgarge\b/gi, 'гараж')
    .replace(/\bgarage\b/gi, 'гараж')
    .replace(/\bdoc\b/gi, 'документ')
    .trim();
  if (/refresh from amo|refresh_from_amo/i.test(code)) return 'Обновление заказа из Amo';
  if (/ingest/i.test(code)) return 'Заказ из Amo';
  if (/buyer update/i.test(human)) return 'Изменён покупатель';
  if (/payment link/i.test(human)) return 'Ссылка на оплату';
  if (/accept cash/i.test(human)) return 'Приём наличных';
  if (/deal.?vehicle|vehicle/i.test(code) && /ocr/i.test(code)) return 'Распознавание СТС';
  if (/deal.?vehicle|doc.?vehicle/i.test(code)) return 'Автомобиль заказа';
  if (human) return human.charAt(0).toUpperCase() + human.slice(1);
  return 'Действие';
}

/** Убрать GUID и тех. шум из summary для истории. */
function auditSummaryClean(raw) {
  return String(raw || '')
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, '')
    .replace(/\b__admin__\b/gi, '')
    .replace(/\bqty\s*=\s*/gi, 'кол-во ')
    .replace(/\bprice\s*=\s*(\d+(?:[.,]\d+)?)/gi, 'цена $1 ₽')
    .replace(/\bamount\s*=\s*(\d+(?:[.,]\d+)?)/gi, 'сумма $1 ₽')
    .replace(/\bfront\s*\+\s*back\b/gi, 'лицевая + оборот')
    .replace(/\bback\s*\+\s*front\b/gi, 'оборот + лицевая')
    .replace(/\bfront\b/gi, 'лицевая')
    .replace(/\bback\b/gi, 'оборот')
    .replace(/\bunknown\b/gi, 'сторона не ясна')
    .replace(/\s·\s*warn\b/gi, ' · есть предупреждения')
    .replace(/\bOCR\b/g, 'распознавание')
    .replace(/\s*·\s*сделка\s*$/i, '')
    .replace(/\s*:\s*,/g, ':')
    .replace(/\s{2,}/g, ' ')
    .replace(/\s+·\s+/g, ' · ')
    .replace(/^[\s·:]+|[\s·]+$/g, '')
    .trim();
}

function auditActorDisplay(it) {
  const id = String(it?.actor_id || '').trim();
  const nameRaw = String(it?.actor_name || '').trim();
  const loginRaw = String(it?.actor_login || '').trim();
  const mapTech = (s) => {
    const t = String(s || '').trim();
    if (!t) return '';
    if (AUDIT_ACTOR_ID_LABELS[t]) return AUDIT_ACTOR_ID_LABELS[t];
    return t;
  };
  // Системный админ / тех. токены — человеческая подпись
  if (id === '__admin__' || nameRaw === '__admin__' || loginRaw === '__admin__') {
    const nice = mapTech(nameRaw);
    if (nice && nice !== 'Админ') return nice;
    return 'Админ';
  }
  const name = mapTech(nameRaw);
  const login = mapTech(loginRaw);
  if (name && login && name.toLowerCase() !== login.toLowerCase() && name !== 'Админ') {
    return name;
  }
  if (name && name !== 'Админ') return name;
  if (login && login !== 'Админ') return login;
  if (name) return name;
  if (login) return login;
  if (id && AUDIT_ACTOR_ID_LABELS[id]) return AUDIT_ACTOR_ID_LABELS[id];
  return '';
}

function auditActionBadgeHtml(action) {
  const code = String(action || '');
  const label = auditActionLabel(code);
  const titleAttr = code && label !== code ? ` title="${esc(code)}"` : '';
  return `<span class="badge source"${titleAttr}>${esc(label)}</span>`;
}

function auditEntityIdLabel(entityId) {
  if (!entityId) return '';
  if (AUDIT_ACTOR_ID_LABELS[entityId]) return AUDIT_ACTOR_ID_LABELS[entityId];
  // Не светим сырые GUID/UUID в UI — только в title
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(entityId)) {
    return '';
  }
  return entityId;
}

function auditEntityRefHtml(entity, entityId) {
  if (!entity) return '';
  const entLabel = AUDIT_ENTITY_LABELS[entity] || entity;
  const idLabel = auditEntityIdLabel(entityId);
  const display = idLabel ? `${entLabel}: ${idLabel}` : entLabel;
  const tech = entityId ? `${entity}: ${entityId}` : entity;
  const titleAttr = tech ? ` title="${esc(tech)}"` : '';
  return `<div class="muted" style="font-size:11px"${titleAttr}>${esc(display)}</div>`;
}

function auditClientCellHtml(it) {
  const ip = String(it.ip || '').trim() || '—';
  const osBrowser = [it.os, it.browser].filter((x) => x && x !== '—').join(' · ');
  const bits = [it.region, osBrowser, it.device && it.device !== 'ПК' ? it.device : '']
    .map((x) => String(x || '').trim())
    .filter(Boolean);
  const tip = [it.user_agent, it.country].filter(Boolean).join('\n');
  return `<td class="mono audit-client-cell" style="font-size:11px;max-width:220px;white-space:normal" title="${esc(tip)}">
    <div>${esc(ip)}</div>
    ${bits.length ? `<div class="muted" style="font-size:10px;line-height:1.35;margin-top:2px">${esc(bits.join(' · '))}</div>` : ''}
  </td>`;
}

function entityHistoryHtml(items, opts = {}) {
  const showActor = opts.showActor !== false;
  const showIp = opts.showIp === true; // по умолчанию скрываем IP — важнее кто/что
  // На карточке сущности объект и так известен — колонку не дублируем
  const showEntity = opts.showEntity === true;
  if (!items.length) {
    return '<p class="muted" style="margin:0">Пока нет записей — появятся после изменений.</p>';
  }
  return `<table class="entity-history-table">
    <thead><tr>
      <th style="width:130px">Когда</th>
      ${showActor ? '<th style="width:160px">Кто</th>' : ''}
      ${showIp ? '<th style="width:180px">IP / клиент</th>' : ''}
      <th>Что сделали</th>
      ${showEntity ? '<th style="width:160px">Объект</th>' : ''}
    </tr></thead>
    <tbody>
      ${items
        .map((it) => {
          const when = esc(String(it.created_at || '').replace('T', ' ').slice(0, 19));
          const whoName = auditActorDisplay(it);
          const who = esc(whoName || '—');
          const actionLabel = auditActionLabel(it.action);
          let summary = auditSummaryClean(it.summary);
          // Если summary = тех. код или пусто — берём подпись действия
          if (!summary || summary === String(it.action || '') || /^[a-z0-9_.]+$/i.test(summary)) {
            summary = actionLabel;
          }
          // Убрать повтор «кто» из текста (колонка «Кто» уже есть)
          if (whoName && whoName !== '—') {
            const whoEsc = whoName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            summary = summary
              .replace(new RegExp('^' + whoEsc + '\\s*·\\s*', 'i'), '')
              .replace(new RegExp('\\s*·\\s*' + whoEsc + '(?=\\s*·|$)', 'i'), '')
              .trim();
          }
          // Колонка «Что» — только действие; «Кто» отдельно. Без колонки — «кто · что».
          let main = summary;
          if (
            !showActor &&
            whoName &&
            whoName !== '—' &&
            !summary.toLowerCase().includes(whoName.toLowerCase())
          ) {
            main = whoName + ' · ' + summary;
          }
          const showSub =
            actionLabel &&
            actionLabel !== '—' &&
            actionLabel !== String(it.action || '') &&
            !main.toLowerCase().includes(actionLabel.toLowerCase()) &&
            // Не дублируем англ. тех. подпись, если в «Что» уже нормальный русский текст
            !(/^[A-Za-z][A-Za-z0-9 ._-]*$/.test(actionLabel) && /[А-Яа-яЁё]/.test(main));
          const what = `
            <div title="${esc(it.action || '')}">${esc(main || actionLabel || '—')}</div>
            ${
              showSub
                ? `<div class="muted" style="font-size:11px">${esc(actionLabel)}</div>`
                : ''
            }
          `;
          const obj = it.entity
            ? auditEntityRefHtml(it.entity, it.entity_id)
            : '<span class="muted">—</span>';
          return `<tr>
            <td class="mono">${when}</td>
            ${showActor ? `<td><b>${who}</b></td>` : ''}
            ${showIp ? auditClientCellHtml(it) : ''}
            <td>${what}</td>
            ${showEntity ? `<td>${obj}</td>` : ''}
          </tr>`;
        })
        .join('')}
    </tbody>
  </table>`;
}

async function fillEntityHistory(mountId, entity, entityId, opts = {}) {
  const el = document.getElementById(mountId);
  if (!el || !entityId) return;
  try {
    const data = await api(
      `/audit?entity=${encodeURIComponent(entity)}&entity_id=${encodeURIComponent(entityId)}&limit=40&page=1`
    );
    el.innerHTML = entityHistoryHtml(data.items || [], opts);
  } catch (e) {
    el.innerHTML = `<p class="error" style="margin:0">${esc(e.message)}</p>`;
  }
}

/**
 * История по всей цепочке заказа (сделка + документы продаж + списания).
 * seed: опционально «создал / создана» из карточки, если ещё нет в audit.
 */
async function fillDealChainHistory(mountId, dealId, opts = {}) {
  const el = document.getElementById(mountId);
  const id = String(dealId || '').trim();
  if (!el || !id) return;
  try {
    const data = await api(
      '/audit?deal_id=' + encodeURIComponent(id) + '&limit=80&page=1'
    );
    let items = Array.isArray(data.items) ? data.items.slice() : [];
    const seed = opts.seed;
    if (seed && seed.created_at) {
      const hasCreate = items.some(
        (it) =>
          String(it.entity || '') === 'crm_deal' &&
          /созда|sync|amo/i.test(String(it.action || '') + ' ' + String(it.summary || ''))
      );
      if (!hasCreate) {
        items.push({
          created_at: seed.created_at,
          actor_name: seed.actor_name || '',
          actor_login: '',
          action: 'crm_deal.create',
          summary: seed.summary || 'Заказ создан / получен из Amo',
          entity: 'crm_deal',
          entity_id: id,
          ip: '',
        });
        items.sort((a, b) =>
          String(b.created_at || '').localeCompare(String(a.created_at || ''))
        );
      }
    }
    el.innerHTML = entityHistoryHtml(items, {
      showEntity: true,
      showIp: false,
      showActor: true,
      ...opts,
    });
  } catch (e) {
    el.innerHTML = `<p class="error" style="margin:0">${esc(e.message)}</p>`;
  }
}

