  /** После OCR — подтянуть чистое ФИО из DaData, если есть близкая подсказка. */
  async function refineOwnerViaDadata(raw) {
    const q = String(raw || '').trim();
    if (q.length < 5) return q;
    try {
      const r = await api('/dadata/fio?q=' + encodeURIComponent(q) + '&count=6');
      const items = r.items || [];
      if (!items.length) return q;
      const qUp = q.toUpperCase().replace(/\s+/g, ' ');
      const qParts = qUp.split(/\s+/).filter(Boolean);
      const score = (val) => {
        const v = String(val || '')
          .toUpperCase()
          .replace(/\s+/g, ' ')
          .trim();
        if (!v) return -1;
        if (v === qUp) return 100;
        let s = 0;
        const vp = v.split(/\s+/);
        for (const p of qParts) {
          if (vp.some((x) => x === p || x.includes(p.slice(0, 4)) || p.includes(x.slice(0, 4)))) s += 10;
        }
        if (vp.length >= 3) s += 5;
        return s;
      };
      let best = items[0];
      let bestS = score(best.value || best.unrestricted_value);
      for (const it of items) {
        const sc = score(it.value || it.unrestricted_value);
        if (sc > bestS) {
          best = it;
          bestS = sc;
        }
      }
      if (bestS < 10) return q;
      return String(best.value || best.unrestricted_value || q).trim() || q;
    } catch (_) {
      return q;
    }
  }
