    if (field === 'amo_channel' && !val) {
      el.value = prev;
      const err = 'Канал реализации обязателен';
      if (msg) msg.textContent = err;
      alert(err);
      return;
    }
    if (field === 'amo_shipment' && !val && /отправк/i.test(String(document.getElementById('deal-amo-channel')?.value || ''))) {
      el.value = prev;
      const err = 'При канале «Отправка» способ отправки обязателен';
      if (msg) msg.textContent = err;
      alert(err);
      return;
    }
    if (
      field === 'amo_payment_type' &&
      !val &&
      /отправк/i.test(String(document.getElementById('deal-amo-channel')?.value || ''))
    ) {
      el.value = prev;
      const err = 'При канале «Отправка» тип оплаты обязателен';
      if (msg) msg.textContent = err;
      alert(err);
      return;
    }
    el.disabled = true;
