async function renderDevPlan() {
  const STATUS_LABEL = {
    planned: 'План',
    in_progress: 'В работе',
    done: 'Готово',
    blocked: 'Блокер',
  };
  if (
    state.devPlanView !== 'table' &&
    state.devPlanView !== 'calendar' &&
    state.devPlanView !== 'map'
  ) {
    state.devPlanView = 'calendar';
  }
  const mode = state.devPlanView;
  view.innerHTML = formChrome(
    'План работ',
    `<p class="muted" style="margin:0;padding:8px 0">Загрузка…</p>`,
    { parentTab: 'dev', parentLabel: 'Разработка' }
  );
  bindFormChrome(() => showSection('dev'));
  let data = { items: [], gantt: { start: '', end: '', days: 1 }, staff: [] };
  try {
    data = await api('/dev-plan');
  } catch (e) {
    view.innerHTML = formChrome(
      'План работ',
      `<p class="error">${esc(e.message)}</p>
       <p class="muted" style="margin:8px 0 0;font-size:12px">Не удалось загрузить план. Обновите страницу или нажмите «Добавить работу» после восстановления.</p>
       <div class="toolbar" style="margin-top:12px">
         <button type="button" class="primary" id="dev-add-retry">Добавить работу</button>
         <button type="button" id="dev-reload">Обновить</button>
       </div>`,
      { parentTab: 'dev', parentLabel: 'Разработка' }
    );
    bindFormChrome(() => showSection('dev'));
    document.getElementById('dev-reload')?.addEventListener('click', () => renderDevPlan());
    document.getElementById('dev-add-retry')?.addEventListener('click', async () => {
      const title = window.prompt('Название работы');
      if (!title || !title.trim()) return;
      try {
        await api('/dev-plan', {
          method: 'POST',
          body: JSON.stringify({
            title: title.trim(),
            block_key: 'sales',
            block_title: 'Продажи',
            block_sort: 10,
            start_date: new Date().toISOString().slice(0, 10),
            end_date: new Date().toISOString().slice(0, 10),
          }),
        });
        state.devPlanView = 'table';
        renderDevPlan();
      } catch (err) {
        alert(err.message || String(err));
      }
    });
    return;
  }
  const items = Array.isArray(data.items) ? data.items : [];
  const deps = Array.isArray(data.deps) ? data.deps : [];
  const staff = Array.isArray(data.staff) ? data.staff : [];
  const range = data.gantt || { start: '', end: '', days: 1 };
  const days = Math.max(1, Number(range.days) || 1);
  const rangeStart = String(range.start || '');
  const rangeEnd = String(range.end || '');
  const dayMs = 86400000;
  const t0 = rangeStart ? Date.parse(rangeStart + 'T12:00:00Z') : Date.now();

  const fmtDay = (iso) => {
    const s = String(iso || '');
    if (s.length < 10) return s;
    return s.slice(8, 10) + '.' + s.slice(5, 7);
  };
  const fmtWhen = (iso) => {
    const s = String(iso || '');
    if (!s) return '';
    return s.length >= 16 ? s.slice(0, 16).replace('T', ' ') : s.slice(0, 10);
  };
  const staffName = (it) =>
    String(it.responsible_name || '').trim() ||
    staff.find((s) => s.id === it.responsible_staff_id)?.name ||
    '—';

  const staffOpts = (selected) =>
    `<option value="">—</option>` +
    staff
      .map(
        (s) =>
          `<option value="${esc(s.id)}" ${s.id === selected ? 'selected' : ''}>${esc(
            s.name || s.id
          )}</option>`
      )
      .join('');

  const commentsHtml = (it) => {
    const list = Array.isArray(it.comments) ? it.comments : [];
    const rows = list.length
      ? list
          .map((c) => {
            const isMove = c.kind === 'reschedule';
            const who = String(c.author_name || '').trim() || '—';
            const when = fmtWhen(c.created_at);
            const moveMeta =
              isMove && (c.old_start || c.new_start)
                ? `<div class="dev-cmt-move muted">${esc(
                    (c.old_start || '—') +
                      (c.old_end && c.old_end !== c.old_start ? '→' + c.old_end : '') +
                      ' → ' +
                      (c.new_start || '—') +
                      (c.new_end && c.new_end !== c.new_start ? '→' + c.new_end : '')
                  )}</div>`
                : '';
            return `<div class="dev-cmt${isMove ? ' is-reschedule' : ''}">
              <div class="dev-cmt-head">
                <span class="dev-cmt-kind">${isMove ? 'Перенос' : 'Коммент'}</span>
                <span class="muted">${esc(who)}${when ? ' · ' + esc(when) : ''}</span>
              </div>
              ${moveMeta}
              <div class="dev-cmt-body">${esc(c.body || '')}</div>
            </div>`;
          })
          .join('')
      : `<div class="muted" style="font-size:11px">Пока нет комментариев</div>`;
    return `<div class="dev-comments" data-dev-comments="${esc(it.id)}">
      <div class="dev-comments-list">${rows}</div>
      <div class="dev-comments-add">
        <input type="text" class="dev-cmt-input" placeholder="Комментарий…" />
        <button type="button" class="dev-cmt-send">Добавить</button>
      </div>
    </div>`;
  };

  const dayLabels = [];
  if (rangeStart) {
    for (let i = 0; i < days; i++) {
      const t = t0 + i * dayMs;
      const d = new Date(t);
      const iso = d.toISOString().slice(0, 10);
      const dow = d.getUTCDay();
      dayLabels.push({
        iso,
        label: fmtDay(iso),
        weekend: dow === 0 || dow === 6,
        show: days <= 21 || i % Math.ceil(days / 14) === 0 || i === days - 1,
      });
    }
  }

  const barPos = (it) => {
    const a = String(it.start_date || '').trim();
    const b = String(it.end_date || it.start_date || '').trim();
    if (!a) return null;
    const ta = Date.parse(a + 'T12:00:00Z');
    const tb = Date.parse((b || a) + 'T12:00:00Z');
    const left = Math.max(0, ((ta - t0) / dayMs / days) * 100);
    const width = Math.max(2.2, (((tb - ta) / dayMs + 1) / days) * 100);
    return { left, width, a, b: b || a };
  };

  const tabBtn = (id, label, ico) => `<button type="button" class="form-pagetab is-stack${
    mode === id ? ' active' : ''
  }" data-dev-view="${id}" role="tab" aria-selected="${
    mode === id ? 'true' : 'false'
  }" data-tip="${esc(label)}">${ico}<span class="pagetab-label">${esc(label)}</span></button>`;
  const icoCal = `<svg class="form-pagetab-ico" viewBox="0 0 16 16" width="15" height="15" aria-hidden="true">
    <rect x="2" y="3" width="12" height="11" rx="1.2" fill="none" stroke="currentColor" stroke-width="1.35"/>
    <path d="M5 2v2.5M11 2v2.5M2 6.5h12" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round"/>
    <rect x="4.2" y="8.2" width="2.2" height="2.2" rx="0.4" fill="currentColor" opacity=".85"/>
    <rect x="7" y="8.2" width="2.2" height="2.2" rx="0.4" fill="currentColor" opacity=".4"/>
    <rect x="9.8" y="8.2" width="2.2" height="2.2" rx="0.4" fill="currentColor" opacity=".4"/>
  </svg>`;
  const icoTable = `<svg class="form-pagetab-ico" viewBox="0 0 16 16" width="15" height="15" aria-hidden="true">
    <rect x="2" y="3" width="12" height="10" rx="1" fill="none" stroke="currentColor" stroke-width="1.4"/>
    <path d="M2 6.5h12M2 10h12M6.5 3v10M10 3v10" fill="none" stroke="currentColor" stroke-width="1.25"/>
  </svg>`;
  const icoMap = `<svg class="form-pagetab-ico" viewBox="0 0 16 16" width="15" height="15" aria-hidden="true">
    <circle cx="4" cy="4" r="2" fill="none" stroke="currentColor" stroke-width="1.35"/>
    <circle cx="12" cy="4" r="2" fill="none" stroke="currentColor" stroke-width="1.35"/>
    <circle cx="8" cy="12" r="2" fill="none" stroke="currentColor" stroke-width="1.35"/>
    <path d="M5.7 5.2 6.8 10.2M10.3 5.2 9.2 10.2M6 4h4" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/>
  </svg>`;
  const viewToggle = `
    <div class="dev-plan-head">
      <div class="form-pagetabs" role="tablist" aria-label="Вид плана">
        ${tabBtn('calendar', 'Календарь', icoCal)}
        ${tabBtn('table', 'Таблица', icoTable)}
        ${tabBtn('map', 'Карта связей', icoMap)}
      </div>
      <div class="dev-plan-actions">
        <button type="button" class="primary" id="dev-add">Добавить работу</button>
        <span class="muted" id="dev-msg" style="font-size:12px"></span>
      </div>
    </div>
    <div class="dev-add-panel" id="dev-add-panel" hidden>
      <input type="text" id="dev-add-title" placeholder="Название работы" maxlength="200" autocomplete="off" />
      <button type="button" class="primary" id="dev-add-save">Создать</button>
      <button type="button" id="dev-add-cancel">Отмена</button>
    </div>`;

  const groupByBlock = (list) => {
    const groups = [];
    const index = new Map();
    for (const it of list) {
      const key = String(it.block_key || 'sales');
      const title = String(it.block_title || 'Продажи');
      let g = index.get(key);
      if (!g) {
        g = { key, title, items: [] };
        index.set(key, g);
        groups.push(g);
      }
      g.items.push(it);
    }
    return groups;
  };
  const blocks = groupByBlock(items);

  let bodyHtml = '';
  if (mode === 'map') {
    const idSet = new Set(items.map((it) => String(it.id)));
    const liveDeps = deps.filter(
      (d) => idSet.has(String(d.item_id)) && idSet.has(String(d.depends_on_id))
    );
    const preds = new Map();
    for (const it of items) preds.set(String(it.id), []);
    for (const d of liveDeps) {
      const list = preds.get(String(d.item_id)) || [];
      list.push(String(d.depends_on_id));
      preds.set(String(d.item_id), list);
    }
    const depth = new Map();
    const depthOf = (id, stack) => {
      if (depth.has(id)) return depth.get(id);
      if (stack.has(id)) return 0;
      stack.add(id);
      let m = 0;
      for (const p of preds.get(id) || []) m = Math.max(m, depthOf(p, stack) + 1);
      stack.delete(id);
      depth.set(id, m);
      return m;
    };
    for (const it of items) depthOf(String(it.id), new Set());
    const cols = new Map();
    for (const it of items) {
      const d = depth.get(String(it.id)) || 0;
      if (!cols.has(d)) cols.set(d, []);
      cols.get(d).push(it);
    }
    const nodeW = 188;
    const nodeH = 78;
    const gapX = 64;
    const gapY = 20;
    const pad = 28;
    const positions = new Map();
    let maxX = pad;
    let maxY = pad;
    [...cols.keys()]
      .sort((a, b) => a - b)
      .forEach((d) => {
        const col = cols.get(d) || [];
        col.forEach((it, i) => {
          const x = pad + d * (nodeW + gapX);
          const y = pad + i * (nodeH + gapY);
          positions.set(String(it.id), { x, y, w: nodeW, h: nodeH, it, ci: d });
          maxX = Math.max(maxX, x + nodeW);
          maxY = Math.max(maxY, y + nodeH);
        });
      });
    const svgW = Math.max(640, maxX + pad);
    const svgH = Math.max(280, maxY + pad);
    const edgePaths = liveDeps
      .map((d, edgeIdx) => {
        const a = positions.get(String(d.depends_on_id));
        const b = positions.get(String(d.item_id));
        if (!a || !b) return '';
        const x1 = a.x + a.w;
        const y1 = a.y + a.h / 2;
        const x2 = b.x;
        const y2 = b.y + b.h / 2;
        // Развести дуги по индексу, чтобы не слипались
        const sn = Math.max(1, liveDeps.length);
        const spread = (edgeIdx - (sn - 1) / 2) * 20;
        const mx = (x1 + x2) / 2;
        const c1y = y1 + spread * 0.45;
        const c2y = y2 + spread * 0.45;
        const tip = (d.depends_on_title || '') + ' → ' + (d.item_title || '') + ' · клик — убрать';
        const dPath = `M${x1},${y1} C${mx},${c1y} ${mx},${c2y} ${x2},${y2}`;
        return `<g class="dev-map-edge-g" data-dep-id="${esc(d.id)}" role="button" tabindex="0" aria-label="${esc(
          'Убрать связь: ' + tip
        )}">
          <title>${esc(tip)}</title>
          <path class="dev-map-edge-hit" d="${dPath}" />
          <path class="dev-map-edge" d="${dPath}" marker-end="url(#dev-map-arrow)" />
        </g>`;
      })
      .join('');
    const nodesHtml = [...positions.values()]
      .map(({ x, y, w, h, it }) => {
        const st = String(it.status || 'planned');
        const inN = (preds.get(String(it.id)) || []).length;
        const outN = liveDeps.filter((d) => String(d.depends_on_id) === String(it.id)).length;
        const fan =
          inN || outN
            ? `<span class="dev-map-fan muted">${
                inN ? '←' + inN : ''
              }${inN && outN ? ' · ' : ''}${outN ? outN + '→' : ''}</span>`
            : '';
        return `<div class="dev-map-node is-${esc(st)}" data-dev-id="${esc(
          it.id
        )}" style="left:${x}px;top:${y}px;width:${w}px;min-height:${h}px">
          <span class="dev-map-port is-in" data-port="in" title="Вход · сюда тянут стрелку" aria-label="Вход связи"></span>
          <span class="dev-map-port is-out" data-port="out" title="Выход · тяните отсюда к другой работе" aria-label="Выход связи"></span>
          <button type="button" class="dev-map-node-del" data-dev-del="${esc(
            it.id
          )}" data-tip="Удалить работу" aria-label="Удалить работу" title="Удалить работу">×</button>
          <div class="dev-map-node-title">${esc(it.title)}</div>
          <div class="dev-map-node-meta muted">${esc(STATUS_LABEL[st] || st)} · ${esc(
            staffName(it)
          )}</div>
          ${fan}
        </div>`;
      })
      .join('');
    const itemOpts = items
      .map((it) => `<option value="${esc(it.id)}">${esc(it.title)}</option>`)
      .join('');
    const depsList = liveDeps.length
      ? `<ul class="dev-map-deps-list">${liveDeps
          .map(
            (d) => `<li data-dep-id="${esc(d.id)}">
            <span><b>${esc(d.item_title || '—')}</b> <span class="muted">зависит от</span> <b>${esc(
              d.depends_on_title || '—'
            )}</b></span>
            <button type="button" class="dev-dep-del" data-dep-id="${esc(
              d.id
            )}" data-tip="Убрать связь">×</button>
          </li>`
          )
          .join('')}</ul>`
      : `<p class="muted" style="margin:0;font-size:12px">Связей пока нет — добавьте ниже.</p>`;
    bodyHtml = `
      <div class="dev-map-wrap">
        <div class="dev-map-canvas" style="width:${svgW}px;height:${svgH}px">
          <svg class="dev-map-svg" width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}" role="img" aria-label="Связи работ">
            <defs>
              <marker id="dev-map-arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto">
                <path d="M0,0 L7,3 L0,6 Z" fill="#0f766e"></path>
              </marker>
            </defs>
            ${edgePaths}
          </svg>
          ${nodesHtml || '<p class="muted" style="padding:24px">Нет работ</p>'}
        </div>
      </div>
      <div class="dev-map-editor">
        <div class="dev-map-editor-head">Связи · что от чего зависит</div>
        <p class="muted" style="margin:0 0 10px;font-size:12px;line-height:1.4">
          Потяните от кружка <b>справа</b> к кружку <b>слева</b> — стрелка
          <b>основание → зависимая</b>. Клик по линии — убрать связь. × на карточке — удалить работу.
        </p>
        <div class="dev-map-add form-grid" style="margin:0 0 12px;align-items:end">
          <label>Эта работа (зависит)
            <select id="dev-dep-item"><option value="">Выберите…</option>${itemOpts}</select>
          </label>
          <label>Зависит от
            <select id="dev-dep-on"><option value="">Выберите…</option>${itemOpts}</select>
          </label>
          <label>Заметка <span class="muted">(необяз.)</span>
            <input id="dev-dep-note" placeholder="почему / условие" autocomplete="off" />
          </label>
          <div>
            <button type="button" class="primary" id="dev-dep-add">Добавить связь</button>
          </div>
        </div>
        ${depsList}
      </div>`;
  } else if (mode === 'calendar') {
    const headDays = dayLabels
      .map(
        (d) =>
          `<div class="dev-cal-day${d.weekend ? ' is-weekend' : ''}${
            d.show ? '' : ' is-tick'
          }" title="${esc(d.iso)}">${d.show ? esc(d.label) : ''}</div>`
      )
      .join('');
    const rowHtml = (it) => {
      const pos = barPos(it);
      const st = String(it.status || 'planned');
      const cN = Array.isArray(it.comments) ? it.comments.length : 0;
      const bar = pos
        ? `<div class="dev-cal-bar is-${esc(st)}" style="left:${pos.left.toFixed(
            2
          )}%;width:${pos.width.toFixed(2)}%" title="${esc(
            it.title +
              ' · ' +
              pos.a +
              (pos.b !== pos.a ? ' → ' + pos.b : '') +
              ' · ' +
              (STATUS_LABEL[st] || st)
          )}">
            <span class="dev-cal-bar-label">${esc(it.title)}</span>
          </div>`
        : `<span class="muted" style="font-size:11px;padding:6px">нет дат</span>`;
      return `<div class="dev-cal-row" data-dev-id="${esc(it.id)}">
        <div class="dev-cal-meta">
          <div class="dev-cal-title">${esc(it.title)}${
            cN ? ` <span class="dev-cmt-badge">${cN}</span>` : ''
          }</div>
          <div class="muted dev-cal-sub">${esc(staffName(it))} · ${esc(
            STATUS_LABEL[st] || st
          )}</div>
          ${
            it.constraint_text
              ? `<div class="dev-cal-constraint" title="${esc(
                  it.constraint_text
                )}">${esc(it.constraint_text)}</div>`
              : ''
          }
        </div>
        <div class="dev-cal-track">${bar}</div>
      </div>`;
    };
    const rows = blocks.length
      ? blocks
          .map(
            (b) =>
              `<div class="dev-cal-block">
                <div class="dev-block-head">${esc(b.title)}</div>
                ${b.items.map(rowHtml).join('')}
              </div>`
          )
          .join('')
      : `<p class="muted" style="margin:12px 0">Нет работ — нажмите «Добавить работу».</p>`;
    bodyHtml = `
      <div class="dev-gantt-axis muted">${
        rangeStart
          ? `Календарь: ${esc(rangeStart)} → ${esc(rangeEnd)} · ${days} дн.`
          : 'Нет дат в плане'
      }</div>
      <div class="dev-cal">
        <div class="dev-cal-head">
          <div class="dev-cal-meta-h">Работа</div>
          <div class="dev-cal-days">${headDays}</div>
        </div>
        <div class="dev-cal-body">${rows}</div>
      </div>
      <div class="dev-cal-legend muted">
        <span><i class="dev-leg is-planned"></i>План</span>
        <span><i class="dev-leg is-in_progress"></i>В работе</span>
        <span><i class="dev-leg is-done"></i>Готово</span>
        <span><i class="dev-leg is-blocked"></i>Блокер</span>
        <span>· клик по строке — таблица и комментарии</span>
      </div>`;
  } else {
    const itemRow = (it) => `<tr data-dev-id="${esc(it.id)}" data-start="${esc(
      it.start_date || ''
    )}" data-end="${esc(it.end_date || '')}">
        <td class="dev-col-title">
          <input class="dev-f" data-f="title" value="${esc(it.title)}" />
          <div class="muted" style="font-size:11px;margin-top:4px">${esc(it.description || '')}</div>
          ${commentsHtml(it)}
        </td>
        <td><input class="dev-f" data-f="start_date" type="date" value="${esc(it.start_date || '')}" /></td>
        <td><input class="dev-f" data-f="end_date" type="date" value="${esc(it.end_date || '')}" /></td>
        <td><select class="dev-f" data-f="responsible_staff_id">${staffOpts(
          it.responsible_staff_id
        )}</select></td>
        <td><textarea class="dev-f" data-f="constraint_text" rows="2">${esc(
          it.constraint_text || ''
        )}</textarea></td>
        <td><textarea class="dev-f" data-f="result_plan" rows="2">${esc(
          it.result_plan || ''
        )}</textarea></td>
        <td><textarea class="dev-f" data-f="result_fact" rows="2">${esc(
          it.result_fact || ''
        )}</textarea></td>
        <td>
          <select class="dev-f" data-f="status">
            ${['planned', 'in_progress', 'done', 'blocked']
              .map(
                (s) =>
                  `<option value="${s}" ${it.status === s ? 'selected' : ''}>${STATUS_LABEL[s]}</option>`
              )
              .join('')}
          </select>
        </td>
        <td><button type="button" class="dev-del" data-tip="Удалить">×</button></td>
      </tr>`;
    const rows = blocks.length
      ? blocks
          .map(
            (b) =>
              `<tr class="dev-block-row"><td colspan="9"><div class="dev-block-head">${esc(
                b.title
              )}</div></td></tr>${b.items.map(itemRow).join('')}`
          )
          .join('')
      : `<tr><td colspan="9" class="muted">Нет работ — добавьте строку.</td></tr>`;
    bodyHtml = `
      <div class="table-scroll">
        <table class="data-table is-dense dev-plan-table">
          <thead>
            <tr>
              <th>Работа / комментарии</th>
              <th>Начало</th>
              <th>Конец</th>
              <th>Ответственный</th>
              <th>Ограничивающее</th>
              <th>Результат (план)</th>
              <th>Фактически</th>
              <th>Статус</th>
              <th></th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
  }

  view.innerHTML = formChrome(
    'План работ',
    `
    ${viewToggle}
    <p class="muted dev-plan-hint">
      ${
        mode === 'calendar'
          ? 'Календарь (Гант). Редактирование, комментарии и перенос сроков — во вкладке «Таблица».'
          : mode === 'map'
            ? 'Карта: тяните стрелку справа→слева. Клик по стрелке или × — убрать. Клик по карточке — таблица.'
            : 'Таблица: при переносе дат укажите причину — она попадёт в комментарии работы.'
      }
    </p>
    ${bodyHtml}
  `,
    {
      parentTab: 'dev',
      parentLabel: 'Разработка',
      titlebarActions: `<button type="button" class="titlebar-action" id="dev-add-tb" data-tip="Добавить работу">+ Работа</button>`,
    }
  );

  const msg = document.getElementById('dev-msg');
  const addPanel = document.getElementById('dev-add-panel');
  const addTitle = document.getElementById('dev-add-title');
  const showAddPanel = () => {
    if (!addPanel) return;
    addPanel.hidden = false;
    if (addTitle) {
      addTitle.value = '';
      setTimeout(() => addTitle.focus(), 0);
    }
    if (msg) msg.textContent = '';
  };
  const hideAddPanel = () => {
    if (addPanel) addPanel.hidden = true;
  };
  const createDevWork = async () => {
    const title = String(addTitle?.value || '').trim();
    if (!title) {
      if (msg) msg.textContent = 'Укажите название';
      addTitle?.focus();
      return;
    }
    try {
      if (msg) msg.textContent = 'Создаём…';
      await api('/dev-plan', {
        method: 'POST',
        body: JSON.stringify({
          title,
          block_key: 'sales',
          block_title: 'Продажи',
          block_sort: 10,
          start_date: new Date().toISOString().slice(0, 10),
          end_date: new Date().toISOString().slice(0, 10),
        }),
      });
      state.devPlanView = 'table';
      renderDevPlan();
    } catch (e) {
      if (msg) msg.textContent = e.message || String(e);
      alert(e.message || String(e));
    }
  };
  // До bindFormChrome — чтобы клик жил даже если enhance таблиц упадёт
  const bindAddClick = (el) => {
    if (!el) return;
    el.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      showAddPanel();
    };
  };
  bindAddClick(document.getElementById('dev-add'));
  bindAddClick(document.getElementById('dev-add-tb'));
  document.getElementById('dev-add-save') &&
    (document.getElementById('dev-add-save').onclick = (e) => {
      e.preventDefault();
      createDevWork();
    });
  document.getElementById('dev-add-cancel') &&
    (document.getElementById('dev-add-cancel').onclick = (e) => {
      e.preventDefault();
      hideAddPanel();
    });
  addTitle?.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      createDevWork();
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      hideAddPanel();
    }
  });

  bindFormChrome(() => showSection('dev'));

  view.querySelectorAll('[data-dev-view]').forEach((btn) => {
    btn.addEventListener('click', () => {
      const v = btn.getAttribute('data-dev-view');
      if (v !== 'calendar' && v !== 'table' && v !== 'map') return;
      if (state.devPlanView === v) return;
      state.devPlanView = v;
      renderDevPlan();
    });
  });

  document.getElementById('dev-dep-add')?.addEventListener('click', async () => {
    const itemId = String(document.getElementById('dev-dep-item')?.value || '').trim();
    const onId = String(document.getElementById('dev-dep-on')?.value || '').trim();
    const note = String(document.getElementById('dev-dep-note')?.value || '').trim();
    if (!itemId || !onId) {
      if (msg) msg.textContent = 'Выберите обе работы';
      return;
    }
    try {
      if (msg) msg.textContent = 'Сохраняем связь…';
      await api('/dev-plan/deps', {
        method: 'POST',
        body: JSON.stringify({ item_id: itemId, depends_on_id: onId, note }),
      });
      state.devPlanView = 'map';
      renderDevPlan();
    } catch (e) {
      if (msg) msg.textContent = e.message || String(e);
      alert(e.message || String(e));
    }
  });
  const removeDevDep = async (depId) => {
    const id = String(depId || '').trim();
    if (!id) return;
    if (!confirm('Убрать эту связь?')) return;
    try {
      if (msg) msg.textContent = 'Убираем связь…';
      await api('/dev-plan/deps/' + encodeURIComponent(id), { method: 'DELETE' });
      state.devPlanView = 'map';
      renderDevPlan();
    } catch (err) {
      if (msg) msg.textContent = err.message || String(err);
      alert(err.message || String(err));
    }
  };
  view.querySelectorAll('.dev-dep-del').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      removeDevDep(btn.getAttribute('data-dep-id'));
    });
  });
  view.querySelectorAll('.dev-map-edge-g[data-dep-id]').forEach((edge) => {
    const onDel = (e) => {
      e.preventDefault();
      e.stopPropagation();
      removeDevDep(edge.getAttribute('data-dep-id'));
    };
    edge.addEventListener('click', onDel);
    edge.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') onDel(e);
    });
  });
  const removeDevItem = async (itemId) => {
    const id = String(itemId || '').trim();
    if (!id) return false;
    if (!confirm('Удалить эту работу и её связи?')) return false;
    try {
      if (msg) msg.textContent = 'Удаление…';
      await api('/dev-plan/' + encodeURIComponent(id), { method: 'DELETE' });
      if (msg) msg.textContent = 'Удалено';
      renderDevPlan();
      return true;
    } catch (err) {
      if (msg) msg.textContent = err.message || String(err);
      alert(err.message || String(err));
      return false;
    }
  };
  view.querySelectorAll('[data-dev-del]').forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      removeDevItem(btn.getAttribute('data-dev-del'));
    });
  });
  view.querySelectorAll('.dev-map-node').forEach((node) => {
    node.addEventListener('click', (e) => {
      if (e.target.closest('.dev-map-port')) return;
      if (e.target.closest('[data-dev-del]')) return;
      if (view.querySelector('.dev-map-canvas.is-linking')) return;
      const id = String(node.getAttribute('data-dev-id') || '').trim();
      state.devPlanView = 'table';
      renderDevPlan();
      if (!id) return;
      setTimeout(() => {
        const tr = document.querySelector(`#view tr[data-dev-id="${CSS.escape(id)}"]`);
        tr?.scrollIntoView?.({ block: 'center', behavior: 'smooth' });
      }, 350);
    });
  });

  if (mode === 'map') {
    const canvas = view.querySelector('.dev-map-canvas');
    const svg = view.querySelector('.dev-map-svg');
    if (canvas && svg) {
      let linkDrag = null;
      const nodeAnchor = (nodeEl, side) => {
        const left = parseFloat(nodeEl.style.left) || 0;
        const top = parseFloat(nodeEl.style.top) || 0;
        const w = nodeEl.offsetWidth || 188;
        const h = nodeEl.offsetHeight || 78;
        return {
          x: side === 'out' ? left + w : left,
          y: top + h / 2,
        };
      };
      const canvasXY = (clientX, clientY) => {
        const r = canvas.getBoundingClientRect();
        return { x: clientX - r.left, y: clientY - r.top };
      };
      const tempPath = () => {
        let p = svg.querySelector('#dev-map-temp-edge');
        if (!p) {
          p = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          p.id = 'dev-map-temp-edge';
          p.setAttribute('class', 'dev-map-edge is-temp');
          p.setAttribute('marker-end', 'url(#dev-map-arrow)');
          svg.appendChild(p);
        }
        return p;
      };
      const drawTemp = (x1, y1, x2, y2) => {
        const mx = (x1 + x2) / 2;
        tempPath().setAttribute('d', `M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}`);
      };
      const clearLinkUi = () => {
        canvas.classList.remove('is-linking');
        view.querySelectorAll('.dev-map-node.is-link-source, .dev-map-node.is-link-target').forEach((n) => {
          n.classList.remove('is-link-source', 'is-link-target');
        });
        view.querySelectorAll('.dev-map-port.is-drop').forEach((p) => p.classList.remove('is-drop'));
        svg.querySelector('#dev-map-temp-edge')?.remove();
        linkDrag = null;
      };
      const endLink = async (e) => {
        if (!linkDrag) return;
        const from = linkDrag;
        window.removeEventListener('pointermove', onLinkMove);
        window.removeEventListener('pointerup', onLinkUp);
        window.removeEventListener('pointercancel', onLinkUp);
        const under = document.elementFromPoint(e.clientX, e.clientY);
        const toNode =
          under?.closest?.('.dev-map-node') ||
          under?.closest?.('.dev-map-port')?.closest?.('.dev-map-node');
        const toId = String(toNode?.getAttribute('data-dev-id') || '').trim();
        const fromId = from.fromId;
        clearLinkUi();
        if (!toId || toId === fromId) return;
        // out → зависит другая; in → зависит эта
        const dependsOnId = from.fromSide === 'out' ? fromId : toId;
        const itemId = from.fromSide === 'out' ? toId : fromId;
        try {
          if (msg) msg.textContent = 'Сохраняем связь…';
          await api('/dev-plan/deps', {
            method: 'POST',
            body: JSON.stringify({ item_id: itemId, depends_on_id: dependsOnId }),
          });
          state.devPlanView = 'map';
          renderDevPlan();
        } catch (err) {
          if (msg) msg.textContent = err.message || String(err);
          alert(err.message || String(err));
        }
      };
      const onLinkMove = (e) => {
        if (!linkDrag) return;
        e.preventDefault();
        const pt = canvasXY(e.clientX, e.clientY);
        drawTemp(linkDrag.x1, linkDrag.y1, pt.x, pt.y);
        view.querySelectorAll('.dev-map-node.is-link-target').forEach((n) => {
          n.classList.remove('is-link-target');
        });
        view.querySelectorAll('.dev-map-port.is-drop').forEach((p) => p.classList.remove('is-drop'));
        const under = document.elementFromPoint(e.clientX, e.clientY);
        const n = under?.closest?.('.dev-map-node');
        const port = under?.closest?.('.dev-map-port');
        if (n && n.getAttribute('data-dev-id') !== linkDrag.fromId) {
          n.classList.add('is-link-target');
        }
        if (port && port.closest('.dev-map-node')?.getAttribute('data-dev-id') !== linkDrag.fromId) {
          port.classList.add('is-drop');
        }
      };
      const onLinkUp = (e) => {
        endLink(e);
      };
      canvas.querySelectorAll('.dev-map-port').forEach((port) => {
        port.addEventListener('pointerdown', (e) => {
          e.preventDefault();
          e.stopPropagation();
          const node = port.closest('.dev-map-node');
          const fromId = String(node?.getAttribute('data-dev-id') || '').trim();
          const fromSide = port.getAttribute('data-port') === 'in' ? 'in' : 'out';
          if (!fromId || !node) return;
          const a = nodeAnchor(node, fromSide);
          linkDrag = { fromId, fromSide, x1: a.x, y1: a.y };
          canvas.classList.add('is-linking');
          node.classList.add('is-link-source');
          drawTemp(a.x, a.y, a.x, a.y);
          window.addEventListener('pointermove', onLinkMove, { passive: false });
          window.addEventListener('pointerup', onLinkUp);
          window.addEventListener('pointercancel', onLinkUp);
        });
      });
    }
  }

  if (mode === 'calendar') {
    view.querySelectorAll('.dev-cal-row[data-dev-id]').forEach((row) => {
      row.addEventListener('click', () => {
        state.devPlanView = 'table';
        renderDevPlan();
      });
    });
    return;
  }

  const saveRow = async (tr, opts = {}) => {
    const id = tr?.dataset?.devId;
    if (!id) return;
    const body = {};
    tr.querySelectorAll('.dev-f').forEach((el) => {
      const f = el.getAttribute('data-f');
      if (!f) return;
      body[f] = el.value;
    });
    const prevStart = String(tr.dataset.start || '');
    const prevEnd = String(tr.dataset.end || '');
    const nextStart = String(body.start_date || '');
    const nextEnd = String(body.end_date || '');
    const datesChanged = nextStart !== prevStart || nextEnd !== prevEnd;
    if (datesChanged) {
      const reason = prompt(
        'Почему переносим срок?\nБыло: ' +
          (prevStart || '—') +
          (prevEnd && prevEnd !== prevStart ? ' → ' + prevEnd : '') +
          '\nСтало: ' +
          (nextStart || '—') +
          (nextEnd && nextEnd !== nextStart ? ' → ' + nextEnd : '')
      );
      if (reason == null) {
        const sEl = tr.querySelector('[data-f="start_date"]');
        const eEl = tr.querySelector('[data-f="end_date"]');
        if (sEl) sEl.value = prevStart;
        if (eEl) eEl.value = prevEnd;
        return;
      }
      if (!String(reason).trim()) {
        alert('Укажите причину переноса срока');
        const sEl = tr.querySelector('[data-f="start_date"]');
        const eEl = tr.querySelector('[data-f="end_date"]');
        if (sEl) sEl.value = prevStart;
        if (eEl) eEl.value = prevEnd;
        return;
      }
      body.reschedule_reason = String(reason).trim();
    }
    try {
      if (msg) msg.textContent = 'Сохранение…';
      await api('/dev-plan/' + encodeURIComponent(id), {
        method: 'PATCH',
        body: JSON.stringify(body),
      });
      if (msg) msg.textContent = 'Сохранено';
      if (opts.reload || datesChanged) renderDevPlan();
      else {
        tr.dataset.start = nextStart;
        tr.dataset.end = nextEnd;
      }
    } catch (e) {
      if (msg) msg.textContent = e.message || String(e);
      alert(e.message || String(e));
      if (datesChanged) {
        const sEl = tr.querySelector('[data-f="start_date"]');
        const eEl = tr.querySelector('[data-f="end_date"]');
        if (sEl) sEl.value = prevStart;
        if (eEl) eEl.value = prevEnd;
      }
    }
  };

  view.querySelectorAll('tr[data-dev-id]').forEach((tr) => {
    tr.querySelectorAll('.dev-f').forEach((el) => {
      const f = el.getAttribute('data-f');
      const reload = f === 'start_date' || f === 'end_date' || f === 'status';
      el.onchange = () => saveRow(tr, { reload });
    });
    const del = tr.querySelector('.dev-del');
    if (del) {
      del.onclick = async () => {
        const id = String(tr.dataset.devId || '').trim();
        if (!id) return;
        del.disabled = true;
        const ok = await removeDevItem(id);
        if (!ok) del.disabled = false;
      };
    }
    const box = tr.querySelector('[data-dev-comments]');
    const send = box?.querySelector('.dev-cmt-send');
    const input = box?.querySelector('.dev-cmt-input');
    const postComment = async () => {
      const id = tr.dataset.devId;
      const text = String(input?.value || '').trim();
      if (!id || !text) return;
      try {
        if (msg) msg.textContent = 'Комментарий…';
        await api('/dev-plan/' + encodeURIComponent(id) + '/comments', {
          method: 'POST',
          body: JSON.stringify({ body: text }),
        });
        renderDevPlan();
      } catch (e) {
        alert(e.message || String(e));
      }
    };
    if (send) send.onclick = postComment;
    if (input) {
      input.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter') {
          ev.preventDefault();
          postComment();
        }
      });
    }
  });
}

