(function bindSideCollapse() {
  const KEY = 'uchet1_side_collapsed';
  const PHONE_KEY = 'uchet1_ui_phone';
  /* ≤1024: телефон + iPad — без постоянного бара, только бургер + overlay */
  const MQ = '(max-width: 1024px)';
  const burger = document.getElementById('btn-burger');
  const phoneBtn = document.getElementById('btn-phone-ui');
  const collapseBtn = document.getElementById('btn-side-collapse');
  const side = document.getElementById('taxi-side');
  const scrim = document.getElementById('taxi-side-scrim');
  const isPhoneUi = () => document.documentElement.classList.contains('ui-phone');
  const isMobile = () => isPhoneUi() || window.matchMedia(MQ).matches;
  const syncBurger = () => {
    if (!burger) return;
    if (isMobile()) {
      const open = document.body.classList.contains('side-flyout-open');
      burger.setAttribute('aria-expanded', open ? 'true' : 'false');
      burger.title = open ? 'Свернуть меню' : 'Открыть меню';
    } else {
      const collapsed = document.body.classList.contains('side-collapsed');
      burger.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
      burger.title = collapsed ? 'Показать меню' : 'Скрыть меню';
    }
  };
  /** На мобиле левый бар только по бургеру — иначе hidden (не rail). */
  const syncMobileSide = () => {
    if (!side) return;
    if (isMobile()) {
      const open = document.body.classList.contains('side-flyout-open');
      side.hidden = !open;
      side.setAttribute('aria-hidden', open ? 'false' : 'true');
    } else {
      side.hidden = false;
      side.removeAttribute('aria-hidden');
    }
  };
  const applyFlyoutDimStyles = (el, on) => {
    if (!el) return;
    if (on) {
      /* Не ставить filter на #view — Chrome на длинных формах рисует белый экран */
      el.style.setProperty('opacity', '0.72', 'important');
      el.style.setProperty('filter', 'none', 'important');
      el.style.setProperty('-webkit-filter', 'none', 'important');
      el.style.setProperty('pointer-events', 'none', 'important');
      el.style.setProperty('background', 'transparent', 'important');
    } else {
      el.style.removeProperty('opacity');
      el.style.removeProperty('filter');
      el.style.removeProperty('-webkit-filter');
      el.style.removeProperty('pointer-events');
      el.style.removeProperty('background');
    }
  };
  const setFlyout = (open) => {
    document.body.classList.toggle('side-flyout-open', !!open);
    document.documentElement.classList.toggle('side-flyout-open', !!open);
    const dim = !!(open && isMobile());
    const viewEl = document.getElementById('view');
    const panelEl = document.getElementById('section-panel');
    viewEl?.classList.toggle('is-flyout-dimmed', dim);
    panelEl?.classList.toggle('is-flyout-dimmed', dim);
    applyFlyoutDimStyles(viewEl, dim);
    applyFlyoutDimStyles(panelEl, dim);
    syncMobileSide();
    syncBurger();
  };
  const syncPhoneBtn = () => {
    if (!phoneBtn) return;
    const on = isPhoneUi();
    phoneBtn.setAttribute('aria-pressed', on ? 'true' : 'false');
    phoneBtn.title = on ? 'Обычный (десктоп) вид' : 'Мобильный вид';
  };
  if (phoneBtn) {
    syncPhoneBtn();
    phoneBtn.addEventListener('click', () => {
      const next = !isPhoneUi();
      document.documentElement.classList.toggle('ui-phone', next);
      try {
        localStorage.setItem(PHONE_KEY, next ? '1' : '0');
      } catch {
        /* ignore */
      }
      setFlyout(false);
      syncPhoneBtn();
      syncBurger();
    });
  }
  const setCollapsed = (collapsed) => {
    document.body.classList.toggle('side-collapsed', collapsed);
    try {
      localStorage.setItem(KEY, collapsed ? '1' : '0');
    } catch {
      /* ignore */
    }
    if (collapseBtn) {
      collapseBtn.title = collapsed ? 'Показать меню' : 'Скрыть меню';
      collapseBtn.setAttribute('aria-label', collapsed ? 'Показать меню' : 'Скрыть меню');
    }
    syncBurger();
    // плавающий бар «Сохранить / Оприходовать» — по ширине main после анимации сайдбара
    schedulePlaceFloatFormDock();
    setTimeout(schedulePlaceFloatFormDock, 200);
  };
  const toggleDesktop = () => setCollapsed(!document.body.classList.contains('side-collapsed'));
  const toggleMobile = () => setFlyout(!document.body.classList.contains('side-flyout-open'));
  const onToggle = () => {
    if (isMobile()) toggleMobile();
    else {
      setFlyout(false);
      toggleDesktop();
    }
  };
  let saved = false;
  try {
    saved = localStorage.getItem(KEY) === '1';
  } catch {
    /* ignore */
  }
  setCollapsed(saved);
  setFlyout(false);
  syncMobileSide();
  if (burger) burger.addEventListener('click', onToggle);
  if (collapseBtn) {
    collapseBtn.addEventListener('click', () => {
      if (isMobile()) toggleMobile();
      else toggleDesktop();
    });
  }
  if (scrim) scrim.addEventListener('click', () => setFlyout(false));
  if (side) {
    side.addEventListener('click', (e) => {
      if (!isMobile()) return;
      const sec = e.target && e.target.closest ? e.target.closest('a.sec') : null;
      if (sec) setFlyout(false);
    });
  }
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && document.body.classList.contains('side-flyout-open')) {
      setFlyout(false);
      return;
    }
    if (e.key === '[' && !e.metaKey && !e.ctrlKey && !e.altKey) {
      const t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
      e.preventDefault();
      onToggle();
    }
  });
  window.matchMedia(MQ).addEventListener('change', () => {
    setFlyout(false);
    syncMobileSide();
    syncBurger();
  });
})();

